<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/includes/notifications.php';
if (current_user()) redirect('student/dashboard.php');
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $name=trim($_POST['full_name']??''); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $phone=preg_replace('/\s+/', '',trim($_POST['phone']??'')); $password=$_POST['password']??'';
    if ($name===''||mb_strlen($name)>150||!$email||strlen($password)<10) $error='Enter your name and a valid email. Your password must be at least 10 characters.';
    else { try { $stmt=$pdo->prepare("INSERT INTO users(full_name,email,phone,password_hash,role) VALUES(?,?,?,?,'student')"); $stmt->execute([$name,$email,$phone?:null,password_hash($password,PASSWORD_DEFAULT)]); $newId=(int)$pdo->lastInsertId(); notify_parties($pdo,$newId,'Welcome to Warwa International School',"Hello {$name},\n\nYour student account is ready. Browse available courses and enroll for KSh 5.\n\nWarwa International School"); session_regenerate_id(true); $_SESSION['user']=['id'=>$newId,'full_name'=>$name,'email'=>$email,'role'=>'student']; $_SESSION['csrf_token']=bin2hex(random_bytes(32)); redirect('student/dashboard.php'); }
        catch(PDOException $e){ if($e->getCode()==='23000')$error='An account with that email already exists.'; else throw $e; } }
}
start_page('Create your account'); ?>
<section class="card auth-card"><p class="eyebrow">STUDENT ENROLMENT</p><h1 class="card-title mt-2 text-2xl">Create your account</h1><p class="muted mt-2">Join Warwa International School and start learning.</p><?php if($error): ?><div class="alert alert-error mt-4"><?= e($error) ?></div><?php endif ?><form method="post" class="mt-6 space-y-4"><?= csrf_field() ?><div><label class="field-label" for="full_name">Full name</label><input class="field" id="full_name" name="full_name" required maxlength="150" autocomplete="name" value="<?= e($_POST['full_name']??'') ?>"></div><div><label class="field-label" for="email">Email address</label><input class="field" id="email" name="email" type="email" required autocomplete="email" value="<?= e($_POST['email']??'') ?>"></div><div><label class="field-label" for="phone">Phone number <span class="font-normal text-slate-400">(optional)</span></label><input class="field" id="phone" name="phone" type="tel" autocomplete="tel" placeholder="07xx xxx xxx" value="<?= e($_POST['phone']??'') ?>"></div><div><label class="field-label" for="password">Password</label><div class="password-wrap"><input class="field" id="password" name="password" type="password" required minlength="10" autocomplete="new-password"><button type="button" class="eye-toggle" data-password-toggle="password" aria-label="Show password"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div><p class="mt-1 text-[11px] text-slate-400">Use at least 10 characters.</p></div><button class="btn-primary w-full">Create account</button></form><p class="mt-5 text-center text-sm text-slate-500">Already registered? <a class="font-bold text-teal-700" href="<?= e(app_url('login.php')) ?>">Sign in</a></p></section><?php end_page(); ?>
